"use client";

import { Easing, interpolate } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  type GradientScaleCutTextElementId,
  gradientScaleCutTextTimeline,
} from "./timeline";

export interface GradientScaleCutTextProps {
  text?: string;
  giantFontSize?: number;
  compactFontSize?: number;
  fontWeight?: number;
  gradientStart?: string;
  gradientEnd?: string;
  ghostColor?: string;
  backgroundColor?: string;
  anchorOffsetX?: number;
  giantTravel?: number;
  settleTravel?: number;
  cutFrame?: number;
  revealSoftness?: number;
  compactBlur?: number;
  speed?: number;
  className?: string;
  /**
   * Moves, trims or stretches the gradient wipe, the giant word and the
   * compact word, by the ids in `./timeline`. Frames on the scene timeline,
   * after `speed`.
   */
  timing?: Timing<GradientScaleCutTextElementId>;
}

export const gradientScaleCutTextLength = 36;

const GIANT_Y = -28;
const GIANT_X_CORRECTION = -48;
const COMPACT_Y = 5;
const COMPACT_X_SCALE = 0.87;
const COMPACT_START_X_CORRECTION = 28;
const FONT_FAMILY = "Arial, Helvetica, sans-serif";
const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

interface TextLayerProps {
  text: string;
  fontSize: number;
  fontWeight: number;
  gradientStart: string;
  gradientEnd: string;
  ghostColor: string;
  maskImage: string;
}

function TextLayer({
  text,
  fontSize,
  fontWeight,
  gradientStart,
  gradientEnd,
  ghostColor,
  maskImage,
}: TextLayerProps) {
  const textStyle = {
    display: "block",
    fontFamily: FONT_FAMILY,
    fontSize,
    fontWeight,
    letterSpacing: 0,
    lineHeight: 1.12,
    whiteSpace: "nowrap" as const,
  };

  return (
    <div style={{ position: "relative" }}>
      <span style={{ ...textStyle, color: ghostColor }}>{text}</span>
      <span
        style={{
          ...textStyle,
          position: "absolute",
          inset: 0,
          color: "transparent",
          backgroundImage: `linear-gradient(90deg, ${gradientStart} 0%, ${gradientStart} 4%, ${gradientEnd} 26%, ${gradientEnd} 100%)`,
          backgroundClip: "text",
          maskImage,
          maskRepeat: "no-repeat",
          opacity: 1,
          WebkitBackgroundClip: "text",
          WebkitMaskImage: maskImage,
          WebkitMaskRepeat: "no-repeat",
        }}
      >
        {text}
      </span>
    </div>
  );
}

export function GradientScaleCutText(props: GradientScaleCutTextProps) {
  const {
    text = "Introducing",
    giantFontSize = 520,
    compactFontSize = 132,
    fontWeight = 700,
    gradientStart = "#f04a14",
    gradientEnd = "#f3f1f1",
    ghostColor = "#170b0a",
    backgroundColor = "#000000",
    anchorOffsetX = -16,
    giantTravel = 400,
    settleTravel = 160,
    revealSoftness = 14,
    compactBlur = 12,
    speed = 1,
    className,
    timing,
  } = props;
  const frame = useSceneFrame() * Math.max(speed, 0);
  const { durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    gradientScaleCutTextTimeline,
    props,
    durationInFrames * Math.max(speed, 0),
    timing,
  );
  const reveal = tl.get("reveal");
  const giant = tl.get("giant");
  const compact = tl.get("compact");
  const cutAt = compact.start;
  const safeGiantFontSize = Math.max(giantFontSize, 1);
  const safeCompactFontSize = Math.max(compactFontSize, 1);
  const safeSoftness = Math.max(revealSoftness, 0);
  const safeBlur = Math.max(compactBlur, 0);
  const revealProgress = interpolate(
    frame,
    [reveal.start, reveal.end],
    [0.02, 1],
    {
      ...clamp,
      easing: Easing.bezier(0.22, 0.74, 0.24, 1),
    },
  );
  const revealEdge = revealProgress * (100 + safeSoftness / 2);
  const revealSolid = Math.max(0, revealEdge - safeSoftness / 2);
  const revealFade = revealEdge + safeSoftness / 2;
  const maskImage = `linear-gradient(90deg, #000 0%, #000 ${revealSolid}%, transparent ${revealFade}%, transparent ${revealFade}%)`;
  const giantProgress = interpolate(frame, [giant.start, giant.end], [0, 1], {
    ...clamp,
    easing: Easing.out(Easing.cubic),
  });
  const settleProgress = interpolate(
    frame,
    [compact.start, compact.end],
    [0, 1],
    {
      ...clamp,
      easing: Easing.out(Easing.cubic),
    },
  );
  const moveProgress = interpolate(
    frame,
    [
      cutAt + compact.beat("moveAt"),
      cutAt + compact.beat("moveMid"),
      cutAt + compact.beat("moveLate"),
      compact.end,
    ],
    [0, 0.58, 0.875, 1],
    clamp,
  );
  const showGiant = frame < cutAt;
  const compactX =
    interpolate(moveProgress, [0, 1], [settleTravel, 0], clamp) +
    COMPACT_START_X_CORRECTION * (1 - moveProgress);
  const compactBlurValue = safeBlur * (1 - settleProgress);

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        backgroundColor,
      }}
    >
      {showGiant ? (
        <div
          style={{
            position: "absolute",
            top: `calc(50% + ${GIANT_Y}px)`,
            left: `calc(50% + ${anchorOffsetX + GIANT_X_CORRECTION - giantTravel * giantProgress}px)`,
            opacity: 1,
            transform: "translate3d(0, -50%, 0)",
          }}
        >
          <TextLayer
            text={text}
            fontSize={safeGiantFontSize}
            fontWeight={fontWeight}
            gradientStart={gradientStart}
            gradientEnd={gradientEnd}
            ghostColor={ghostColor}
            maskImage={maskImage}
          />
        </div>
      ) : (
        <div
          style={{
            position: "absolute",
            top: `calc(50% + ${COMPACT_Y}px)`,
            left: `calc(50% + ${anchorOffsetX + compactX}px)`,
            filter: `blur(${compactBlurValue}px)`,
            opacity: 1,
            transform: `translate3d(-50%, -50%, 0) scaleX(${COMPACT_X_SCALE})`,
            transformOrigin: "center",
          }}
        >
          <TextLayer
            text={text}
            fontSize={safeCompactFontSize}
            fontWeight={fontWeight}
            gradientStart={gradientStart}
            gradientEnd={gradientEnd}
            ghostColor={ghostColor}
            maskImage={maskImage}
          />
        </div>
      )}
    </div>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The gradient wiping across the word, the giant word drifting left, and the
// cut to the compact word settling in place. Frames on the 30 fps scene
// timeline, after `speed`. The ids are public: a saved `timing` prop refers
// to them.

export type GradientScaleCutTextElementId = "reveal" | "giant" | "compact";

export interface GradientScaleCutTextTimingProps {
  /** Frame the giant word cuts to the compact one. */
  cutFrame?: number;
}

const CUT_FRAME = 13;
/** The gradient finishes its wipe on this frame. */
const REVEAL_END = 33;
/** The compact word sheds its blur over `SETTLE_FRAMES` after the cut. */
const SETTLE_FRAMES = 8;
/** Its slide holds a frame, then eases through these keys from the cut. */
const MOVE_AT = 1;
const MOVE_MID = 2;
const MOVE_LATE = 4;

// The giant word travels until the frame before the cut; the compact word
// follows it, so stretching the giant word moves the cut.
export const gradientScaleCutTextTimeline = defineTimeline<
  GradientScaleCutTextElementId,
  GradientScaleCutTextTimingProps
>(
  ({
    cutFrame = CUT_FRAME,
  }): TimelineElement<GradientScaleCutTextElementId>[] => {
    const safeCutFrame = Math.max(cutFrame, 1);
    return [
      {
        id: "reveal",
        lane: "Gradient",
        label: "gradient wipe",
        start: 0,
        length: REVEAL_END,
      },
      {
        id: "giant",
        lane: "Word",
        label: "giant word",
        start: 0,
        length: Math.max(safeCutFrame - 1, 1),
      },
      {
        id: "compact",
        lane: "Word",
        label: "compact word",
        start: safeCutFrame,
        length: SETTLE_FRAMES,
        follows: "giant",
        beats: { moveAt: MOVE_AT, moveMid: MOVE_MID, moveLate: MOVE_LATE },
      },
    ];
  },
);
